import { toast } from "@zuccadev-labs/zuix-zui/dom";

document.querySelector("#commands").addEventListener("z:select", (event) => {
  toast({ title: "Command: " + event.detail.value });
});

import { confirm } from "@zuccadev-labs/zuix-zui/dom";

document.querySelector("#delete").addEventListener("click", async () => {
  const ok = await confirm({ title: "Delete project?", description: "This cannot be undone.", intent: "danger", confirmLabel: "Delete" });
  if (ok) removeProject();
});

